<?php
declare(strict_types=1);
$cfgFile=__DIR__.'/config.php'; if(!is_file($cfgFile)){http_response_code(500);exit('أنشئ config.php أولاً من config.example.php');}
$c=require $cfgFile; try{$pdo=new PDO('mysql:host='.$c['db_host'].';dbname='.$c['db_name'].';charset=utf8mb4',$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}catch(Throwable $e){exit('تعذر الاتصال بقاعدة البيانات. تحقق من config.php');}
$count=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&$count===0){$u=trim($_POST['username']??'');$p=$_POST['password']??'';if(strlen($u)<4||strlen($p)<12)$msg='اسم المستخدم 4 أحرف على الأقل وكلمة المرور 12 حرفاً على الأقل.';else{$s=$pdo->prepare('INSERT INTO admins(username,password_hash) VALUES(?,?)');$s->execute([$u,password_hash($p,PASSWORD_DEFAULT)]);$count=1;$msg='تم إنشاء المدير. احذف ملف setup-admin.php الآن.';}}
?><!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>إعداد مدير المتجر</title><body style="font-family:Tahoma,Arial;background:#f4f7f4;padding:30px"><main style="max-width:430px;margin:7vh auto;background:white;padding:25px;border-radius:16px"><h2>إنشاء حساب مدير OFOQ</h2><?php if($msg)echo '<p>'.htmlspecialchars($msg,ENT_QUOTES,'UTF-8').'</p>';if($count===0):?><form method="post"><p>اسم المستخدم</p><input name="username" required minlength="4" style="width:100%;padding:12px"><p>كلمة المرور (12 حرفاً على الأقل)</p><input type="password" name="password" required minlength="12" style="width:100%;padding:12px"><p><button style="margin-top:15px;padding:12px 20px;background:#13834a;color:white;border:0;border-radius:9px">إنشاء المدير</button></p></form><?php else:?><p>يوجد حساب مدير بالفعل. لأمان متجرك احذف هذا الملف من الاستضافة.</p><?php endif;?></main></body></html>
